{'role': 'user', 'content': [{'tool_use_id': 'toolu_01PPsjUSxmR6bm2A1ZYpgzPj', 'type': 'tool_result', 'content': '     1→import { useRouteStatus, useRouteSetupStatus, useFixRoute } from "../../api/network";
     2→
     3→export function RouteStatusBanner() {
     4→  const { data: route, refetch: refetchRoute } = useRouteStatus();
     5→  const { data: setup } = useRouteSetupStatus();
     6→  const fixMutation = useFixRoute();
     7→
     8→  if (!route || !route.route_applicable) {
     9→    return null; // Not macOS or not applicable
    10→  }
    11→
    12→  const handleFix = async () => {
    13→    if (!route.expected_interface) return;
    14→    try {
    15→      await fixMutation.mutateAsync(route.expected_interface);
    16→      refetchRoute();
    17→    } catch {
    18→      // Error handled by mutation state
    19→    }
    20→  };
    21→
    22→  if (route.correct) {
    23→    return (
    24→      <div className="rounded-lg bg-green-900/30 px-4 py-3">
    25→        <div className="flex items-center gap-2">
    26→          <div className="w-2 h-2 rounded-full bg-green-500" />
    27→          <span className="text-sm text-green-400">
    28→            Route OK: 169.254.255.255 &rarr; {route.current_interface}
    29→          </span>
    30→        </div>
    31→      </div>
    32→    );
    33→  }
    34→
    35→  // Route is wrong
    36→  const canFix = setup?.sudoers_installed ?? false;
    37→
    38→  return (
    39→    <div className="rounded-lg bg-yellow-900/30 px-4 py-3 space-y-2">
    40→      <div className="flex items-center justify-between">
    41→        <div className="flex items-center gap-2">
    42→          <div className="w-2 h-2 rounded-full bg-yellow-500" />
    43→          <span className="text-sm text-yellow-400">
    44→            Route mismatch: 169.254.255.255 &rarr; {route.current_interface ?? "none"}
    45→            {route.expected_interface && (
    46→              <span className="text-gray-400">
    47→                {" "}(should be {route.expected_interface})
    48→              </span>
    49→            )}
    50→          </span>
    51→        </div>
    52→        {canFix && (
    53→          <button
    54→            type="button"
    55→            onClick={handleFix}
    56→            disabled={fixMutation.isPending}
    57→            className="rounded bg-yellow-600 px-3 py-1 text-xs font-medium text-white hover:bg-yellow-500 disabled:opacity-50"
    58→          >
    59→            {fixMutation.isPending ? "Fixing..." : "Fix Now"}
    60→          </button>
    61→        )}
    62→      </div>
    63→      {!canFix && setup && (
    64→        <div className="text-xs text-gray-400">
    65→          Route fix not available. Run:{" "}
    66→          <code className="rounded bg-gray-800 px-1.5 py-0.5 text-gray-300">
    67→            {setup.setup_command}
    68→          </code>
    69→        </div>
    70→      )}
    71→      {fixMutation.isError && (
    72→        <div className="text-xs text-red-400">
    73→          Fix failed: {(fixMutation.error as Error).message}
    74→        </div>
    75→      )}
