{'role': 'user', 'content': [{'tool_use_id': 'toolu_01Dy2wyYN3aa8kzfXZfXPvB7', 'type': 'tool_result', 'content': '     1→/** Network API functions and TanStack Query hooks for interface/route management. */
     2→
     3→import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
