     5→import type {
     6→  InterfaceListResponse,
     7→  RouteStatusResponse,
     8→  RouteFixResponse,
     9→  RouteSetupStatus,
    10→  BridgeState,
    11→} from "../types";
    12→
    13→// --- Query hooks ---
    14→
    15→export function useInterfaces() {
    16→  return useQuery<InterfaceListResponse>({
    17→    queryKey: ["network", "interfaces"],
    18→    queryFn: () => apiFetch<InterfaceListResponse>("/network/interfaces"),
    19→    refetchOnWindowFocus: true,
    20→    staleTime: 10_000,
    21→  });
    22→}
    23→
    24→export function useRouteStatus() {
    25→  return useQuery<RouteStatusResponse>({
    26→    queryKey: ["network", "route"],
    27→    queryFn: () => apiFetch<RouteStatusResponse>("/network/route"),
    28→    refetchOnWindowFocus: true,
    29→    staleTime: 5_000,
    30→  });
    31→}
    32→
    33→export function useRouteSetupStatus() {
    34→  return useQuery<RouteSetupStatus>({
    35→    queryKey: ["network", "route", "setup-status"],
    36→    queryFn: () => apiFetch<RouteSetupStatus>("/network/route/setup-status"),
    37→    staleTime: 60_000,
    38→  });
    39→}
    40→
    41→// --- Mutation functions ---
    42→
    43→export async function fixRoute(iface: string): Promise<RouteFixResponse> {
    44→  return apiFetch<RouteFixResponse>("/network/route/fix", {
    45→    method: "POST",
    46→    body: JSON.stringify({ interface: iface }),
    47→  });
    48→}
    49→
    50→export async function updateBridgeInterface(iface: string): Promise<unknown> {
    51→  return apiFetch("/bridge/settings", {
    52→    method: "PUT",
    53→    body: JSON.stringify({ network_interface: iface }),
    54→  });
    55→}
    56→
    57→export async function restartBridge(): Promise<BridgeState> {
    58→  return apiFetch<BridgeState>("/bridge/restart", {
    59→    method: "POST",
    60→  });
    61→}
    62→
    63→// --- Mutation hooks ---
    64→
    65→export function useFixRoute() {
    66→  const queryClient = useQueryClient();
    67→  return useMutation({
    68→    mutationFn: fixRoute,
    69→    onSuccess: () => {
    70→      queryClient.invalidateQueries({ queryKey: ["network", "route"] });
    71→    },
    72→  });
    73→}
    74→
    75→export function useRestartBridge() {
    76→  const queryClient = useQueryClient();
    77→  return useMutation({
    78→    mutationFn: restartBridge,
    79→    onSuccess: () => {
    80→      queryClient.invalidateQueries({ queryKey: ["network", "route"] });
    81→    },
    82→  });
